#!/usr/bin/env python3
"""Writes `sui/tests/fixtures.move`, the Move tests' fixtures, and `test/fixtures/sui/vault-attest.json`, the vector the
Solidity side checks the vault's `attest` record against. Move tests cannot read files, so every fixture becomes a
function returning its bytes. Nothing here is computed by the vault's own code:

- the repository's real data: mainnet receipts (`test/fixtures/ethereum/receipts.json`), SP1 v6's own Groth16 fixture
  (`prototype/evm/test/SP1VerifierGroth16V6.t.sol`) and verifying key (`prototype/evm/src/sp1/Groth16Verifier.sol`),
  RISC Zero's v3.0 receipt and verifying key (`vendor/risc0-ethereum`), and a real hub's storage for this vault's
  snapshot exit (`hub.json`, written by `generate.py`);
- Solidity's own encoder for every encoding the vault writes or reads (`cast abi-encode`, `cast keccak`): a message, its
  log data, the index and intake digests, the hub's slot keys, the vault token's id, and `attest`'s record.

Needs foundry's `cast`. From the repository root, after `generate.py`:

    python3 sui/tests/fixtures/vectors.py
"""

import json
import os
import re
import subprocess

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", "..", ".."))
OUT = os.path.join(HERE, "..", "fixtures.move")
ATTEST_OUT = os.path.join(ROOT, "test", "fixtures", "sui", "vault-attest.json")

SEPOLIA = 11_155_111
SUI_TESTNET = 10_803_649_406_359_875_205
ATTEST_DOMAIN = "0xb0ec2b25fdd79b42b523d5b0e641474599bbba254460db808de33f7bc0c25d5c"
DOMAIN = "0xbd3cf7d103abd331f0285cc3baa9b84878b3a414fec18667ce7824a74f7004a0"
INDEX_DIGEST_DOMAIN = "0xdf4e41877859fe1e24a1c7d90334348c094634ae191591983221bdba2ada064b"
INTAKE_DIGEST_DOMAIN = "0x73bc63cbb2438f9ca78af51ef010ac754ee98b02f528cf72c876da9a84dd01f9"
ZERO = "0x" + "00" * 32
ZERO_ADDRESS = "0x" + "00" * 20


def cast(*args):
    return subprocess.run(["cast", *args], capture_output=True, text=True, check=True).stdout.strip()


def keccak(hexdata):
    return cast("keccak", hexdata)


def enc(types, *values):
    return cast("abi-encode", f"f({types})", *[str(v) for v in values])


def word(x):
    return "0x" + format(x, "064x")


def read(path):
    with open(os.path.join(ROOT, path)) as f:
        return f.read()


def nodes(proof):
    """A node list as the vault's proofs carry it: count (u8), then each node's length (u32, little-endian) and bytes."""
    out = bytes([len(proof)])
    for n in proof:
        b = bytes.fromhex(n[2:])
        out += len(b).to_bytes(4, "little") + b
    return "0x" + out.hex()


def sol_uint(source, name):
    m = re.search(r"uint256 constant " + re.escape(name) + r" = (0x[0-9a-fA-F]+|\d+);", source)
    return int(m.group(1), 0)


def sol_hex(source, name):
    m = re.search(re.escape(name) + r"\s*=?\s*(?:bytes32\()?\s*(?:hex\")?(0x)?([0-9a-fA-F]+)", source)
    return "0x" + m.group(2)


class Move:
    def __init__(self):
        self.lines = []

    def bytes(self, name, value):
        value = value[2:] if value.startswith("0x") else value
        self.lines.append(f"public fun {name}(): vector<u8> {{ x\"{value.lower()}\" }}")

    def list(self, name, values):
        inner = ", ".join(f"x\"{v[2:].lower()}\"" for v in values)
        self.lines.append(f"public fun {name}(): vector<vector<u8>> {{ vector[{inner}] }}")

    def u64(self, name, value):
        assert 0 <= int(value) < 2**64, name
        self.lines.append(f"public fun {name}(): u64 {{ {int(value)} }}")

    def u256(self, name, value):
        self.lines.append(f"public fun {name}(): u256 {{ {int(value)} }}")

    def write(self):
        head = (
            "// Generated by `sui/tests/fixtures/vectors.py` from the repository's real data and Solidity's own encoder:\n"
            "// do not edit by hand.\n"
            "#[test_only]\n"
            "module xindex_vault::fixtures;\n\n"
        )
        with open(OUT, "w") as f:
            f.write(head + "\n\n".join(self.lines) + "\n")


def receipts(m):
    f = json.loads(read("test/fixtures/ethereum/receipts.json"))
    m.u64("block_number", f["number"])
    m.u64("block_timestamp", f["timestamp"])
    m.bytes("block_state_root", f["stateRoot"])
    m.bytes("block_receipts_root", f["receiptsRoot"])
    for i, case in enumerate(f["cases"]):
        m.u64(f"case{i}_tx", case["txIndex"])
        m.u64(f"case{i}_log", case["logIndex"])
        m.bytes(f"case{i}_nodes", nodes(case["proof"]))
        m.bytes(f"case{i}_emitter", case["emitter"])
        m.bytes(f"case{i}_topic0", case["topic0"])
        m.bytes(f"case{i}_topic1", case["topic1"])
        m.bytes(f"case{i}_data", case["data"])
    for name in ("failed", "absent", "oneTopic"):
        m.u64(f"{name.lower()}_tx", f[name]["txIndex"])
        m.bytes(f"{name.lower()}_nodes", nodes(f[name]["proof"]))
    m.u64("onetopic_log", f["oneTopic"]["logIndex"])
    m.bytes("malformed_receipts_root", f["malformed"]["receiptsRoot"])
    m.bytes("malformed_nodes", nodes(f["malformed"]["proof"]))


def proofs(m):
    t = read("prototype/evm/test/SP1VerifierGroth16V6.t.sol")
    m.bytes("sp1_program_key", sol_hex(t, "PROGRAM_VKEY ="))
    m.bytes("sp1_public_values", sol_hex(t, "PUBLIC_VALUES ="))
    m.bytes("sp1_proof", sol_hex(t, "PROOF_BYTES ="))
    t = read("vendor/risc0-ethereum/test/TestReceiptV3_0.sol")
    m.bytes("risc0_image_id", sol_hex(t, "IMAGE_ID ="))
    m.bytes("risc0_journal", sol_hex(t, "JOURNAL ="))
    m.bytes("risc0_seal", sol_hex(t, "SEAL ="))
    # The verifying keys as the Solidity verifiers hold them, for the tests that rebuild the prepared keys.
    g = read("prototype/evm/src/sp1/Groth16Verifier.sol")
    for name in ("ALPHA_X", "ALPHA_Y", "BETA_NEG_X_0", "BETA_NEG_X_1", "BETA_NEG_Y_0", "BETA_NEG_Y_1",
                 "GAMMA_NEG_X_0", "GAMMA_NEG_X_1", "GAMMA_NEG_Y_0", "GAMMA_NEG_Y_1", "DELTA_NEG_X_0",
                 "DELTA_NEG_X_1", "DELTA_NEG_Y_0", "DELTA_NEG_Y_1", "CONSTANT_X", "CONSTANT_Y") + tuple(
            f"PUB_{i}_{c}" for i in range(5) for c in "XY"):
        m.u256("sp1_" + name.lower(), sol_uint(g, name))
    g = read("vendor/risc0-ethereum/src/groth16/Groth16Verifier.sol")
    for name in ("alphax", "alphay", "betax1", "betax2", "betay1", "betay2", "gammax1", "gammax2", "gammay1",
                 "gammay2", "deltax1", "deltax2", "deltay1", "deltay2") + tuple(
            f"IC{i}{c}" for i in range(6) for c in "xy"):
        m.u256("risc0_" + name.lower(), sol_uint(g, name))


def hub(m, h):
    m.u64("hub_source_chain_id", h["source_chain_id"])
    m.u64("hub_chain_id", h["chain_id"])
    m.bytes("hub_vault", h["vault"])
    m.bytes("hub_factory", h["factory"])
    m.bytes("hub_implementation", h["hub_implementation"])
    m.bytes("hub_index", h["index"])
    m.bytes("hub_salt", h["salt"])
    m.bytes("hub_sui_token", h["sol_token"])
    m.u64("hub_block", h["block"])
    m.u64("hub_timestamp", h["timestamp"])
    m.bytes("hub_state_root", h["state_root"])
    for name in ("settled_intake", "open_intake"):
        m.bytes(f"{name}_id", h[name]["id"])
        m.u64(f"{name}_deadline", h[name]["deadline"])
        m.u64(f"{name}_amount", int(h[name]["amount"]))
        m.bytes(f"{name}_proof", h[name]["proof"]["proof"])
        m.bytes(f"{name}_slot", h[name]["proof"]["slots"][0])
        m.bytes(f"{name}_mark", h[name]["proof"]["values"][0])
    for name in ("burn", "migrate", "unsent_burn"):
        m.bytes(f"{name}_payload", h[name]["payload"])
        m.bytes(f"{name}_id", h[name]["id"])
        m.bytes(f"{name}_proof", h[name]["proof"]["proof"])
        m.bytes(f"{name}_slot", h[name]["proof"]["slots"][0])
        m.bytes(f"{name}_mark", h[name]["proof"]["values"][0])
    m.bytes("burn_recipient", h["burn"]["recipient"])
    m.bytes("migrate_new_index", h["migrate"]["new_index"])
    m.bytes("migrate_new_salt", h["migrate"]["new_salt"])
    m.bytes("absent_account", h["absent_account"]["address"])
    m.bytes("absent_account_proof", h["absent_account"]["proof"]["proof"])
    for who in ("holder_a", "holder_b"):
        x = h[who]
        m.bytes(f"{who}", x["address"])
        m.bytes(f"{who}_recipient", x["recipient"])
        for c, claim in enumerate(x["claims"]):
            m.list(f"{who}_claim{c}_slots", claim["slots"])
            m.list(f"{who}_claim{c}_values", claim["values"])
            m.bytes(f"{who}_claim{c}_proof", claim["proof"])
    m.bytes("holder_a_digest", h["holder_a"]["digest"])
    m.bytes("holder_a_signature", h["holder_a"]["signature"])
    m.bytes("holder_a_past_the_end_proof", h["holder_a"]["past_the_end"]["proof"])
    m.list("holder_a_past_the_end_values", h["holder_a"]["past_the_end"]["values"])


def encodings(m, h):
    """Solidity's own encodings of what the vault writes and reads, for this vault's ids."""
    vault, chain, index = h["vault"], SUI_TESTNET, h["index"]
    # A message, its id and its log data.
    body = enc("bytes32,uint256,bytes32", ZERO, 123_456_789, "0x" + "ab" * 32)
    payload = enc("bytes32,uint256,uint8,uint256,bytes32,address,uint256,bytes", DOMAIN, SEPOLIA, 1, chain, vault,
                  index, 7, body)
    m.bytes("enc_burn_body", body)
    m.bytes("enc_payload", payload)
    m.bytes("enc_payload_id", keccak(payload))
    m.bytes("enc_log_data", enc("bytes", payload))
    # Digests: an index never credited, one credited, an intake open and one settled.
    m.bytes("enc_index_digest_empty", keccak(enc("bytes32,uint256,bytes32,address,address[],uint256[],uint256[]",
                                                 INDEX_DIGEST_DOMAIN, chain, vault, index, "[]", "[]", "[]")))
    m.bytes("enc_index_digest", keccak(enc("bytes32,uint256,bytes32,address,address[],uint256[],uint256[]",
                                           INDEX_DIGEST_DOMAIN, chain, vault, index, f"[{ZERO_ADDRESS}]",
                                           "[5000000000]", "[1250]")))
    intake = word((1_800_003_600 << 192) | 7)
    m.bytes("enc_intake_id", intake)
    m.bytes("enc_intake_digest_open", keccak(enc("bytes32,uint256,bytes32,address,uint256,uint8,address[],uint256[]",
                                                 INTAKE_DIGEST_DOMAIN, chain, vault, index, intake, 1,
                                                 f"[{ZERO_ADDRESS}]", "[3000000000]")))
    m.bytes("enc_intake_digest_none", keccak(enc("bytes32,uint256,bytes32,address,uint256,uint8,address[],uint256[]",
                                                 INTAKE_DIGEST_DOMAIN, chain, vault, index, intake, 3, "[]", "[]")))
    # The hub's slot keys.
    m.bytes("enc_index_slot", keccak(enc("address,uint256", index, 14)))
    inner = keccak(enc("address,uint256", index, 15))
    m.bytes("enc_intake_slot", keccak(enc("uint256,bytes32", intake, inner)))
    m.bytes("enc_vault_token", "0x" + keccak(enc("bytes32,uint256,bytes32", keccak("0x" + b"xindex.v4.vault-token".hex()),
                                                 chain, ZERO))[-40:])


def attest(m, h):
    """`attest`'s record for a vault whose index is registered and whose intake `attest_intake_id` holds a deposit of
    3 SUI, as the Move test makes it at the harness's time, and the same record from Solidity's encoder: the vector the
    Solidity side checks (`test/SuiStateVerifier.vault.t.sol`)."""
    vault, chain, index = h["vault"], SUI_TESTNET, h["index"]
    start = h["settled_intake"]["deadline"] - 600  # `harness::new`'s clock
    intake = word(((start + 3600) << 192) | 77)
    index_slot = keccak(enc("address,uint256", index, 14))
    intake_slot = keccak(enc("uint256,bytes32", intake, keccak(enc("address,uint256", index, 15))))
    index_digest = keccak(enc("bytes32,uint256,bytes32,address,address[],uint256[],uint256[]",
                              INDEX_DIGEST_DOMAIN, chain, vault, index, "[]", "[]", "[]"))
    intake_digest = keccak(enc("bytes32,uint256,bytes32,address,uint256,uint8,address[],uint256[]",
                               INTAKE_DIGEST_DOMAIN, chain, vault, index, intake, 1, f"[{ZERO_ADDRESS}]",
                               "[3000000000]"))
    slots = [index_slot, intake_slot, word(25)]
    values = [index_digest, intake_digest, ZERO]
    timestamp_ms = (start + 1000) * 1000 + 456
    record = enc("bytes32,uint256,bytes32,uint256,bytes32[],bytes32[]", ATTEST_DOMAIN, chain, vault, timestamp_ms,
                 "[" + ",".join(slots) + "]", "[" + ",".join(values) + "]")
    m.bytes("attest_intake_id", intake)
    m.u64("attest_timestamp_ms", timestamp_ms)
    m.list("attest_slots", slots)
    m.list("attest_values", values)
    m.bytes("attest_record", record)
    os.makedirs(os.path.dirname(ATTEST_OUT), exist_ok=True)
    with open(ATTEST_OUT, "w") as f:
        json.dump({
            "chainId": str(chain),
            "vaultId": vault,
            "timestampMs": timestamp_ms,
            "slots": slots,
            "values": values,
            "record": record,
        }, f, indent=1)
        f.write("\n")


def rlp_bytes(b):
    if len(b) == 1 and b[0] < 0x80:
        return b
    return rlp_len(0x80, len(b)) + b


def rlp_list(items):
    body = b"".join(items)
    return rlp_len(0xC0, len(body)) + body


def rlp_len(base, n):
    if n < 56:
        return bytes([base + n])
    be = n.to_bytes((n.bit_length() + 7) // 8, "big")
    return bytes([base + 55 + len(be)]) + be


def h2b(x):
    return bytes.fromhex(x[2:] if x.startswith("0x") else x)


def event_proof(emitter, payload, number, timestamp):
    """`harness::event_proof`, precomputed so a gas test spends nothing building it: the log's legacy receipt alone in
    its block's receipts trie, the block alone under its headers root."""
    pid = h2b(keccak("0x" + payload.hex()))
    data = h2b(enc("bytes", "0x" + payload.hex()))
    topic = h2b(keccak("0x" + b"VaultMessage(bytes32,bytes)".hex()))
    log = rlp_list([rlp_bytes(emitter), rlp_list([rlp_bytes(topic), rlp_bytes(pid)]), rlp_bytes(data)])
    receipt = rlp_list([rlp_bytes(b"\x01"), rlp_bytes(b"\x52\x08"), rlp_bytes(bytes(256)), rlp_list([log])])
    leaf = rlp_list([rlp_bytes(b"\x20\x80"), rlp_bytes(receipt)])
    receipts_root = h2b(keccak("0x" + leaf.hex()))
    state = bytes([7] * 32)
    root = h2b(keccak("0x" + (number.to_bytes(32, "big") + timestamp.to_bytes(32, "big") + state + receipts_root).hex()))
    proof = root + number.to_bytes(8, "little") + timestamp.to_bytes(8, "little") + state + receipts_root + b"\x00"
    proof += b"\x01" + len(leaf).to_bytes(4, "little") + leaf + bytes(8)
    return "0x" + proof.hex(), "0x" + root.hex()


def bloated(m, h, sizes):
    """LG-1's receipt: the vault message's log, then another log of `k` bytes of data, as a permissionless call that also
    emits logs makes it; the message's proof, precomputed, for each size."""
    vault, index = h["vault"], h["index"]
    payload = h2b(enc("bytes32,uint256,uint8,uint256,bytes32,address,uint256,bytes", DOMAIN, SEPOLIA, 2, SUI_TESTNET,
                      vault, index, 1, word(1)))
    pid = h2b(keccak("0x" + payload.hex()))
    topic = h2b(keccak("0x" + b"VaultMessage(bytes32,bytes)".hex()))
    ours = rlp_list([rlp_bytes(h2b(index)), rlp_list([rlp_bytes(topic), rlp_bytes(pid)]),
                     rlp_bytes(h2b(enc("bytes", "0x" + payload.hex())))])
    m.bytes("bloated_payload", "0x" + payload.hex())
    for k in sizes:
        filler = rlp_list([rlp_bytes(bytes([0x11] * 20)), rlp_list([rlp_bytes(bytes(32))]), rlp_bytes(bytes(k))])
        receipt = rlp_list([rlp_bytes(b"\x01"), rlp_bytes(b"\x52\x08"), rlp_bytes(bytes(256)), rlp_list([ours, filler])])
        leaf = rlp_list([rlp_bytes(b"\x20\x80"), rlp_bytes(receipt)])
        receipts_root = h2b(keccak("0x" + leaf.hex()))
        state = bytes([7] * 32)
        number, timestamp = 10, 20
        root = h2b(keccak("0x" + (number.to_bytes(32, "big") + timestamp.to_bytes(32, "big") + state +
                                  receipts_root).hex()))
        proof = root + number.to_bytes(8, "little") + timestamp.to_bytes(8, "little") + state + receipts_root + b"\x00"
        proof += b"\x01" + len(leaf).to_bytes(4, "little") + leaf + bytes(8)
        m.bytes(f"bloated_{k}_proof", "0x" + proof.hex())
        m.bytes(f"bloated_{k}_root", "0x" + root.hex())


def gas(m, h):
    """A settle and a burn of the harness's index, with their proofs, for the gas tests."""
    vault, index = h["vault"], h["index"]
    start = h["settled_intake"]["deadline"] - 600
    intake = word(((start + 3600) << 192) | 1)
    settle = h2b(enc("bytes32,uint256,uint8,uint256,bytes32,address,uint256,bytes", DOMAIN, SEPOLIA, 2, SUI_TESTNET,
                     vault, index, 1, intake))
    proof, root = event_proof(h2b(index), settle, 1_001, start)
    m.bytes("gas_intake", intake)
    m.bytes("gas_settle", "0x" + settle.hex())
    m.bytes("gas_settle_proof", proof)
    m.bytes("gas_settle_root", root)
    body = enc("bytes32,uint256,bytes32", ZERO, 100 * 10**9, word(0xBEEF))
    burn = h2b(enc("bytes32,uint256,uint8,uint256,bytes32,address,uint256,bytes", DOMAIN, SEPOLIA, 1, SUI_TESTNET,
                   vault, index, 2, body))
    proof, root = event_proof(h2b(index), burn, 1_002, start)
    m.bytes("gas_burn", "0x" + burn.hex())
    m.bytes("gas_burn_proof", proof)
    m.bytes("gas_burn_root", root)


def main():
    with open(os.path.join(HERE, "hub.json")) as f:
        h = json.load(f)
    m = Move()
    receipts(m)
    proofs(m)
    hub(m, h)
    encodings(m, h)
    attest(m, h)
    gas(m, h)
    bloated(m, h, (2_000, 8_000, 16_000, 32_000))
    m.write()
    print(f"wrote {OUT} and {ATTEST_OUT}")


if __name__ == "__main__":
    main()
